/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ minutes: NonNullable<unknown> }} Email_Otp_ExpiryInputs */

const en_email_otp_expiry = /** @type {(inputs: Email_Otp_ExpiryInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`The code expires in ${i?.minutes} minutes and can be used only once.`)
};

const zh_cn2_email_otp_expiry = /** @type {(inputs: Email_Otp_ExpiryInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`The code expires in ${i?.minutes} minutes and can be used only once.`)
};

const ja_email_otp_expiry = /** @type {(inputs: Email_Otp_ExpiryInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`コードは __VAR_ minutes__ 分で期限切れになり、使用できるのは 1 回だけです。 ${i?.minutes}`)
};

/**
* | output |
* | --- |
* | "The code expires in {minutes} minutes and can be used only once." |
*
* @param {Email_Otp_ExpiryInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const email_otp_expiry = /** @type {((inputs: Email_Otp_ExpiryInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Email_Otp_ExpiryInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_email_otp_expiry(inputs)
	if (locale === "ja") return ja_email_otp_expiry(inputs)
	return en_email_otp_expiry(inputs)
});