/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ organizationName: NonNullable<unknown> }} Email_Memberjoined_TitleInputs */

const en_email_memberjoined_title = /** @type {(inputs: Email_Memberjoined_TitleInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`New teammate in ${i?.organizationName}`)
};

const zh_cn2_email_memberjoined_title = /** @type {(inputs: Email_Memberjoined_TitleInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`New teammate in ${i?.organizationName}`)
};

const ja_email_memberjoined_title = /** @type {(inputs: Email_Memberjoined_TitleInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.organizationName} の新しいチームメイト`)
};

/**
* | output |
* | --- |
* | "New teammate in {organizationName}" |
*
* @param {Email_Memberjoined_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const email_memberjoined_title = /** @type {((inputs: Email_Memberjoined_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Email_Memberjoined_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_email_memberjoined_title(inputs)
	if (locale === "ja") return ja_email_memberjoined_title(inputs)
	return en_email_memberjoined_title(inputs)
});