/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ inviterName: NonNullable<unknown>, organizationName: NonNullable<unknown> }} Email_Invite_SubjectInputs */

const en_email_invite_subject = /** @type {(inputs: Email_Invite_SubjectInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.inviterName} invited you to ${i?.organizationName} on cms`)
};

const zh_cn2_email_invite_subject = /** @type {(inputs: Email_Invite_SubjectInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.inviterName} invited you to ${i?.organizationName} on cms`)
};

const ja_email_invite_subject = /** @type {(inputs: Email_Invite_SubjectInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.inviterName} さんがあなたを cms の ${i?.organizationName} に招待しました`)
};

/**
* | output |
* | --- |
* | "{inviterName} invited you to {organizationName} on cms" |
*
* @param {Email_Invite_SubjectInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const email_invite_subject = /** @type {((inputs: Email_Invite_SubjectInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Email_Invite_SubjectInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_email_invite_subject(inputs)
	if (locale === "ja") return ja_email_invite_subject(inputs)
	return en_email_invite_subject(inputs)
});