/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ memberName: NonNullable<unknown>, organizationName: NonNullable<unknown> }} Email_Memberjoined_MessageInputs */

const en_email_memberjoined_message = /** @type {(inputs: Email_Memberjoined_MessageInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.memberName} just joined ${i?.organizationName} and can now collaborate on its documentation.`)
};

const zh_cn2_email_memberjoined_message = /** @type {(inputs: Email_Memberjoined_MessageInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.memberName} just joined ${i?.organizationName} and can now collaborate on its documentation.`)
};

const ja_email_memberjoined_message = /** @type {(inputs: Email_Memberjoined_MessageInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.memberName} は ${i?.organizationName} に参加し、そのドキュメントで共同作業できるようになりました。`)
};

/**
* | output |
* | --- |
* | "{memberName} just joined {organizationName} and can now collaborate on its documentation." |
*
* @param {Email_Memberjoined_MessageInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const email_memberjoined_message = /** @type {((inputs: Email_Memberjoined_MessageInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Email_Memberjoined_MessageInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_email_memberjoined_message(inputs)
	if (locale === "ja") return ja_email_memberjoined_message(inputs)
	return en_email_memberjoined_message(inputs)
});