/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ projectName: NonNullable<unknown> }} Email_Deployment_Ready_TitleInputs */

const en_email_deployment_ready_title = /** @type {(inputs: Email_Deployment_Ready_TitleInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.projectName} is live`)
};

const zh_cn2_email_deployment_ready_title = /** @type {(inputs: Email_Deployment_Ready_TitleInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.projectName} is live`)
};

const ja_email_deployment_ready_title = /** @type {(inputs: Email_Deployment_Ready_TitleInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.projectName} はライブです`)
};

/**
* | output |
* | --- |
* | "{projectName} is live" |
*
* @param {Email_Deployment_Ready_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const email_deployment_ready_title = /** @type {((inputs: Email_Deployment_Ready_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Email_Deployment_Ready_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_email_deployment_ready_title(inputs)
	if (locale === "ja") return ja_email_deployment_ready_title(inputs)
	return en_email_deployment_ready_title(inputs)
});