/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ inviterName: NonNullable<unknown>, organizationName: NonNullable<unknown>, role: NonNullable<unknown> }} Email_Invite_MessageInputs */

const en_email_invite_message = /** @type {(inputs: Email_Invite_MessageInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.inviterName} invited you to collaborate on documentation in ${i?.organizationName} as ${i?.role}.`)
};

const zh_cn2_email_invite_message = /** @type {(inputs: Email_Invite_MessageInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.inviterName} invited you to collaborate on documentation in ${i?.organizationName} as ${i?.role}.`)
};

const ja_email_invite_message = /** @type {(inputs: Email_Invite_MessageInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.inviterName} は、${i?.role} として ${i?.organizationName} のドキュメントで共同作業するようあなたを招待しました。`)
};

/**
* | output |
* | --- |
* | "{inviterName} invited you to collaborate on documentation in {organizationName} as {role}." |
*
* @param {Email_Invite_MessageInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const email_invite_message = /** @type {((inputs: Email_Invite_MessageInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Email_Invite_MessageInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_email_invite_message(inputs)
	if (locale === "ja") return ja_email_invite_message(inputs)
	return en_email_invite_message(inputs)
});