/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ organizationName: NonNullable<unknown> }} Email_Invite_PreviewInputs */

const en_email_invite_preview = /** @type {(inputs: Email_Invite_PreviewInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Join ${i?.organizationName} on cms.`)
};

const zh_cn2_email_invite_preview = /** @type {(inputs: Email_Invite_PreviewInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Join ${i?.organizationName} on cms.`)
};

const ja_email_invite_preview = /** @type {(inputs: Email_Invite_PreviewInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`cms で ${i?.organizationName} に参加します。`)
};

/**
* | output |
* | --- |
* | "Join {organizationName} on cms." |
*
* @param {Email_Invite_PreviewInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const email_invite_preview = /** @type {((inputs: Email_Invite_PreviewInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Email_Invite_PreviewInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_email_invite_preview(inputs)
	if (locale === "ja") return ja_email_invite_preview(inputs)
	return en_email_invite_preview(inputs)
});