import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ ipAddress: NonNullable<unknown> }} Email_Newsignin_WithipInputs */

const en_email_newsignin_withip = /** @type {(inputs: Email_Newsignin_WithipInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`We noticed a new sign-in to your account from a new location (IP ${i?.ipAddress}).`)
};

const zh_cn2_email_newsignin_withip = /** @type {(inputs: Email_Newsignin_WithipInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`We noticed a new sign-in to your account from a new location (IP ${i?.ipAddress}).`)
};

const ja_email_newsignin_withip = /** @type {(inputs: Email_Newsignin_WithipInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`新しい場所 (IP ${i?.ipAddress}) からアカウントへの新しいサインインが検出されました。`)
};

/**
* | output |
* | --- |
* | "We noticed a new sign-in to your account from a new location (IP {ipAddress})." |
*
* @param {Email_Newsignin_WithipInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const email_newsignin_withip = /** @type {((inputs: Email_Newsignin_WithipInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Email_Newsignin_WithipInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_email_newsignin_withip(inputs)
	if (locale === "ja") return ja_email_newsignin_withip(inputs)
	return en_email_newsignin_withip(inputs)
});