/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ days: NonNullable<unknown> }} Email_Invite_ExpiryInputs */

const en_email_invite_expiry = /** @type {(inputs: Email_Invite_ExpiryInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`This invitation expires in ${i?.days} days.`)
};

const zh_cn2_email_invite_expiry = /** @type {(inputs: Email_Invite_ExpiryInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`This invitation expires in ${i?.days} days.`)
};

const ja_email_invite_expiry = /** @type {(inputs: Email_Invite_ExpiryInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`この招待状は ${i?.days} 日後に期限切れになります。`)
};

/**
* | output |
* | --- |
* | "This invitation expires in {days} days." |
*
* @param {Email_Invite_ExpiryInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const email_invite_expiry = /** @type {((inputs: Email_Invite_ExpiryInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Email_Invite_ExpiryInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_email_invite_expiry(inputs)
	if (locale === "ja") return ja_email_invite_expiry(inputs)
	return en_email_invite_expiry(inputs)
});