/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ projectName: NonNullable<unknown>, version: NonNullable<unknown> }} Email_Deployment_Ready_PreviewInputs */

const en_email_deployment_ready_preview = /** @type {(inputs: Email_Deployment_Ready_PreviewInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.projectName} version ${i?.version} published successfully.`)
};

const zh_cn2_email_deployment_ready_preview = /** @type {(inputs: Email_Deployment_Ready_PreviewInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.projectName} version ${i?.version} published successfully.`)
};

const ja_email_deployment_ready_preview = /** @type {(inputs: Email_Deployment_Ready_PreviewInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.projectName} バージョン ${i?.version} が正常に公開されました。`)
};

/**
* | output |
* | --- |
* | "{projectName} version {version} published successfully." |
*
* @param {Email_Deployment_Ready_PreviewInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const email_deployment_ready_preview = /** @type {((inputs: Email_Deployment_Ready_PreviewInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Email_Deployment_Ready_PreviewInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_email_deployment_ready_preview(inputs)
	if (locale === "ja") return ja_email_deployment_ready_preview(inputs)
	return en_email_deployment_ready_preview(inputs)
});