/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ memberName: NonNullable<unknown>, organizationName: NonNullable<unknown> }} Email_Memberjoined_SubjectInputs */

const en_email_memberjoined_subject = /** @type {(inputs: Email_Memberjoined_SubjectInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.memberName} joined ${i?.organizationName}`)
};

const zh_cn2_email_memberjoined_subject = /** @type {(inputs: Email_Memberjoined_SubjectInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.memberName} joined ${i?.organizationName}`)
};

const ja_email_memberjoined_subject = /** @type {(inputs: Email_Memberjoined_SubjectInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.memberName} が ${i?.organizationName} に参加しました`)
};

/**
* | output |
* | --- |
* | "{memberName} joined {organizationName}" |
*
* @param {Email_Memberjoined_SubjectInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const email_memberjoined_subject = /** @type {((inputs: Email_Memberjoined_SubjectInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Email_Memberjoined_SubjectInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_email_memberjoined_subject(inputs)
	if (locale === "ja") return ja_email_memberjoined_subject(inputs)
	return en_email_memberjoined_subject(inputs)
});