/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ organizationName: NonNullable<unknown> }} Email_Invite_TitleInputs */

const en_email_invite_title = /** @type {(inputs: Email_Invite_TitleInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`You're invited to ${i?.organizationName}`)
};

const zh_cn2_email_invite_title = /** @type {(inputs: Email_Invite_TitleInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`You're invited to ${i?.organizationName}`)
};

const ja_email_invite_title = /** @type {(inputs: Email_Invite_TitleInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.organizationName} に招待されています`)
};

/**
* | output |
* | --- |
* | "You're invited to {organizationName}" |
*
* @param {Email_Invite_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const email_invite_title = /** @type {((inputs: Email_Invite_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Email_Invite_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_email_invite_title(inputs)
	if (locale === "ja") return ja_email_invite_title(inputs)
	return en_email_invite_title(inputs)
});