import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ projectName: NonNullable<unknown>, version: NonNullable<unknown> }} Email_Deployment_Failed_SubjectInputs */

const en_email_deployment_failed_subject = /** @type {(inputs: Email_Deployment_Failed_SubjectInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.projectName} publish failed (v${i?.version})`)
};

const zh_cn2_email_deployment_failed_subject = /** @type {(inputs: Email_Deployment_Failed_SubjectInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.projectName} publish failed (v${i?.version})`)
};

const ja_email_deployment_failed_subject = /** @type {(inputs: Email_Deployment_Failed_SubjectInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.projectName} の公開に失敗しました (v${i?.version})`)
};

/**
* | output |
* | --- |
* | "{projectName} publish failed (v{version})" |
*
* @param {Email_Deployment_Failed_SubjectInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const email_deployment_failed_subject = /** @type {((inputs: Email_Deployment_Failed_SubjectInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Email_Deployment_Failed_SubjectInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_email_deployment_failed_subject(inputs)
	if (locale === "ja") return ja_email_deployment_failed_subject(inputs)
	return en_email_deployment_failed_subject(inputs)
});