/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ version: NonNullable<unknown>, projectName: NonNullable<unknown> }} Email_Deployment_Failed_MessageInputs */

const en_email_deployment_failed_message = /** @type {(inputs: Email_Deployment_Failed_MessageInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Publishing version v${i?.version} of ${i?.projectName} failed.`)
};

const zh_cn2_email_deployment_failed_message = /** @type {(inputs: Email_Deployment_Failed_MessageInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Publishing version v${i?.version} of ${i?.projectName} failed.`)
};

const ja_email_deployment_failed_message = /** @type {(inputs: Email_Deployment_Failed_MessageInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.projectName} のバージョン v${i?.version} の公開に失敗しました。`)
};

/**
* | output |
* | --- |
* | "Publishing version v{version} of {projectName} failed." |
*
* @param {Email_Deployment_Failed_MessageInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const email_deployment_failed_message = /** @type {((inputs: Email_Deployment_Failed_MessageInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Email_Deployment_Failed_MessageInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_email_deployment_failed_message(inputs)
	if (locale === "ja") return ja_email_deployment_failed_message(inputs)
	return en_email_deployment_failed_message(inputs)
});